    22→export const MessageContentBottomSheet: React.FC<Props> = ({ roomId }) => {
    23→  const ref = useRef<BottomSheetModal>(null);
    24→  const fadeIn = useRef(
    25→    animateSequence(
    26→      { opacity: [0, 1] },
    27→      {
    28→        duration: 200,
    29→      },
    30→    ),
    31→  ).current;
    32→  const [payload, setPayload] = useAtom(TimelineAtoms.longPressPayload);
    33→  const avatarUrl = useMemo(() => {
    34→    return payload?.event.senderProfile.tag === ProfileDetails_Tags.Ready
    35→      ? payload?.event.senderProfile.inner.avatarUrl
    36→      : null;
    37→  }, [payload]);
    38→  const displayName = useMemo(() => {
    39→    return payload?.event.senderProfile.tag === ProfileDetails_Tags.Ready
    40→      ? payload?.event.senderProfile.inner.displayName
    41→      : undefined;
    42→  }, [payload]);
    43→  const setReplyPayload = useSetAtom(TimelineAtoms.replyPayload);
    44→  const setEditPayload = useSetAtom(TimelineAtoms.editPayload);
    45→  const setForwardPayload = useSetAtom(TimelineAtoms.forwardPayload);
    46→  const canEditOrR = useMemo(
    47→    () => payload?.event.isOwn && payload?.messageType === "text",
    48→    [payload],
    49→  );
    50→  const isTextMessage = useMemo(
    51→    () => payload?.messageType === "text",
    52→    [payload],
    53→  );
    54→
    55→  const handleBottomSheetClose = useCallback(() => {
    56→    fadeIn.reverse(() => {
    57→      setPayload(null);
    58→    });
    59→  }, [fadeIn, setPayload]);
    60→
    61→  const handleReply = useCallback(() => {
    62→    if (!payload) return;
    63→    const eventId = getEventId(payload.event);
    64→    if (!eventId) return;
    65→
    66→    setEditPayload(null);
    67→    setReplyPayload({
    68→      eventId,
    69→      senderName: displayName ?? payload.event.sender,
    70→      content: payload.content,
    71→    });
    72→
    73→    ref.current?.dismiss();
    74→  }, [payload, displayName, setEditPayload, setReplyPayload]);
    75→
    76→  const handleEdit = useCallback(() => {
    77→    if (!payload?.event.isOwn || payload?.messageType !== "text") return;
    78→
    79→    setReplyPayload(null);
    80→    setEditPayload({
    81→      event: payload.event,
    82→      senderName: displayName ?? payload.event.sender,
    83→      content: payload.content,
    84→    });
    85→    ref.current?.dismiss();
    86→  }, [displayName, payload, setEditPayload, setReplyPayload]);
    87→
    88→  const handleForward = useCallback(() => {
    89→    if (!payload) return;
    90→
    91→    setForwardPayload(payload);
    92→    ref.current?.dismiss();
    93→    NavigationContainerRef.navigate("forwardMessage", {
    94→      currentRoomId: roomId,
    95→    });
    96→  }, [payload, setForwardPayload]);
    97→
    98→  const handleDelete = useCallback(async () => {
    99→    if (!payload?.event.isOwn) return;
   100→
   101→    try {
   102→      await MatrixService.deleteMessage(roomId, payload.event);
   103→      setEditPayload(null);
   104→      setReplyPayload(null);
   105→    } catch (error) {
   106→      console.error("Failed to delete message:", error);
   107→    } finally {
   108→      ref.current?.dismiss();
   109→    }
   110→  }, [payload, roomId, setEditPayload, setReplyPayload]);
   111→
   112→  const handleCopy = () => {
   113→    if (!payload?.content) return;
   114→    Clipboard.setString(payload.content);
   115→    Toast.show({
   116→      text1: "Message copied to clipboard",
   117→      type: "success",
   118→    });
   119→    ref.current?.dismiss();
   120→  };
   121→
   122→  useEffect(() => {
   123→    if (!payload) return;
   124→
   125→    fadeIn.start();
   126→    ref.current?.present();
   127→  }, [payload, fadeIn]);
   128→
   129→  if (!payload) return null;
   130→
   131→  return (
   132→    <Block
   133→      absolute
   134→      width="100%"
   135→      height="100%"
   136→      offsets={{ left: 0, bottom: 0 }}
   137→      animations={fadeIn.animations}
   138→      zIndex={9999}
   139→      background={Colors.black70}
   140→    >
   141→      <BottomSheetModal
   142→        ref={ref}
   143→        handleStyle={styles.handle}
   144→        handleIndicatorStyle={styles.handleIndicator}
   145→        backgroundStyle={styles.background}
   146→        enablePanDownToClose
   147→        enableDynamicSizing
   148→        onDismiss={handleBottomSheetClose}
   149→      >
   150→        <BottomSheetView>
   151→          <Block
   152→            paddings={{
   153→              paddingHorizontal: 20,
   154→              paddingBottom: 20,
   155→            }}
   156→            gap={16}
   157→            align="center"
   158→          >
   159→            <Block
   160→              width="100%"
   161→              flexDirection="row"
   162→              gap={16}
   163→              align="center"
   164→              justify="space-between"
   165→              margins={{ marginBottom: 32 }}
   166→            >
   167→              <Block flexDirection="row" gap={16} align="center" flex={1}>
   168→                <UserImage
   169→                  avatarUrl={avatarUrl}
   170→                  displayName={displayName}
   171→                  height={40}
   172→                  width={40}
   173→                />
   174→                <Block>
   175→                  <Text color={Colors.primary}>{displayName}</Text>
   176→                  <Text numberOfLines={3} flex={1}>
   177→                    {payload.content}
   178→                  </Text>
   179→                </Block>
   180→              </Block>
   181→              <Text color={Colors.white50}>
   182→                {format(Number(payload.event.timestamp), "HH:mm")}
   183→              </Text>
   184→            </Block>
   185→            <Block width="100%">
   186→              <MessageContentListItem
   187→                title="Reply"
   188→                icon={require("assets/icons/reply.png")}
   189→                onPress={handleReply}
   190→              />
   191→              <MessageContentListItem
   192→                title="Forward"
   193→                icon={require("assets/icons/forward.png")}
   194→                onPress={handleForward}
   195→              />
   196→              {canEdit && (
   197→                <MessageContentListItem
   198→                  title="Edit"
   199→                  icon={require("assets/icons/edit.png")}
   200→                  onPress={handleEdit}
   201→                />
   202→              )}
   203→              {isTextMessage && (
   204→                <MessageContentListItem
   205→                  title="Copy"
   206→                  tintColor={Colors.white30}
   207→                  icon={require("assets/icons/copy.png")}
   208→                  onPress={handleCopy}
   209→                />
   210→              )}
   211→              <MessageContentListItem
   212→                title="Remove message"
   213→                icon={require("assets/icons/trash.png")}
   214→                onPress={handleDelete}
   215→                tintColor={Colors.error}
   216→                textColor={Colors.error}
   217→              />
   218→            </Block>
   219→          </Block>
   220→        </BottomSheetView>
   221→      </BottomSheetModal>
   222→    </Block>
   223→  );
   224→};
   225→
   226→const styles = StyleSheet.create({
   227→  background: {
   228→    backgroundColor: Colors.blackMinus1,
   229→    borderTopLeftRadius: 24,
   230→    borderTopRightRadius: 24,
   231→  },
   232→  handle: {
   233→    borderWidth: 1,
   234→    borderBottomWidth: 0,
   235→    borderTopLeftRadius: 24,
   236→    borderTopRightRadius: 24,
   237→    paddingHorizontal: 12,
   238→    paddingTop: 12,
   239→    paddingBottom: 24,
   240→  },
   241→  handleIndicator: {
   242→    width: 84,
   243→    height: 4,
   244→    backgroundColor: Colors.white50,
   245→  },
   246→});
