    73→const dataPath = `${RNFS.DocumentDirectoryPath}/matrix/data`;
    74→const cachePath = `${RNFS.CachesDirectoryPath}/matrix/cache`;
    75→
    76→const APP_ID = "com.prototyp.cloak";
    77→
    78→export class MatrixService {
    79→  //TODO: change every method that uses MatrixService.instance to a class method
    80→  public static instance: ClientInterface | null;
    81→  public static syncService: SyncServiceInterface | null;
    82→  private static verificationController: SessionVerificationControllerInterface | null =
    83→    null;
    84→  public static profile: UserProfile | null = null;
    85→
    86→  // Verification callbacks
    87→  private static onVerificationRequest: VerificationRequestCallback | null =
    88→    null;
    89→  private static onVerificationEmojis: VerificationEmojisCallback | null = null;
    90→  private static onVerificationStateChange: VerificationStateChangeCallback | null =
    91→    null;
    92→
    93→  /** Clear the crypto store directories to fix device ID mismatches */
    94→  private static async clearCryptoStore() {
    95→    try {
    96→      const dataExists = await RNFS.exists(dataPath);
    97→      const cacheExists = await RNFS.exists(cachePath);
    98→
    99→      if (dataExists) {
   100→        await RNFS.unlink(dataPath);
   101→        console.log("Cleared crypto data store");
   102→      }
   103→
   104→      if (cacheExists) {
   105→        await RNFS.unlink(cachePath);
   106→        console.log("Cleared crypto cache store");
   107→      }
   108→    } catch (error) {
   109→      console.warn("Failed to clear crypto store:", error);
   110→    }
   111→  }
   112→
   113→  /** Initialize client with error handling for RTC warnings */
   114→  public static async initialize(serverUrl: string) {
   115→    this.instance = await new ClientBuilder()
   116→      .serverNameOrHomeserverUrl(serverUrl)
   117→      .sessionPaths(dataPath, cachePath) // enables persistent stores (needed for E2EE)
   118→      .autoEnableBackups(false)
   119→      .build();
   120→  }
   121→
   122→  public static getServerName = () => {
   123→    if (!this.instance) return null;
   124→    return this.instance.server() || this.instance.homeserver();
   125→  };
   126→
   127→  // public static isLoggedIn = () => this.instance.isLoggedIn();
   128→
   129→  /** Check if there are stored credentials available for auto-login */
   130→  public static hasStoredCredentials = (): boolean => {
   131→    return MatrixStorage.hasStoredCredentials();
   132→  };
   133→
   134→  /** Attempt to restore session from stored credentials */
   135→  public static restoreSession = async (): Promise<boolean> => {
   136→    try {
   137→      const credentials = MatrixStorage.getLoginCredentials();
   138→
   139→      if (!credentials) return false;
   140→
   141→      await this.initialize(credentials.baseUrl);
   142→
   143→      if (!this.instance) throw new Error("Failed to initialize client");
   144→
   145→      // Create client with stored credentials
   146→      await this.instance.restoreSession({
   147→        accessToken: credentials.accessToken,
   148→        refreshToken: credentials.refreshToken,
   149→        userId: credentials.userId,
   150→        deviceId: credentials.deviceId,
   151→        homeserverUrl: credentials.baseUrl,
   152→        oidcData: undefined,
   153→        slidingSyncVersion: SlidingSyncVersion.Native,
   154→      });
   155→
   156→      // Verify the session is valid by making a server request
   157→      try {
   158→        this.profile = await this.instance.getProfile(credentials.userId);
   159→      } catch (error) {
   160→        console.warn("Session validation failed:", error);
   161→        throw new Error("Session is invalid or expired");
   162→      }
   163→
   164→      this.syncService = await this.instance.syncService().finish();
   165→
   166→      if (!this.syncService) {
   167→        throw new Error("Failed to initialize sync service");
   168→      }
   169→
   170→      await this.syncService.start();
   171→
   172→      // Update atoms so providers can react to the initialized service
   173→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
   174→      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
   175→      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
   176→
   177→      return true;
   178→    } catch (error) {
   179→      console.warn("Failed to restore session:", error);
   180→
   181→      // Clear both credentials and crypto store to ensure clean state
   182→      MatrixStorage.clearLoginCredentials();
   183→      await this.clearCryptoStore();
   184→
   185→      // Reset the instance so it can be recreated fresh
   186→      this.instance = null;
   187→      this.syncService = null;
   188→
   189→      // Clear atoms
   190→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
   191→      MatrixJotaiStore.set(MatrixAtoms.syncService, null);
   192→
   193→      return false;
   194→    }
   195→  };
   196→
   197→  /** Call this after logging in to create a new client instance with the provided account.  */
   198→  public static setup = async (params: Session) => {
   199→    // Clear any existing crypto store to prevent device ID mismatches
   200→    await this.clearCryptoStore();
   201→
   202→    // Stop and clear existing instances
   203→    if (this.syncService) await this.syncService.stop();
   204→    this.instance = null;
   205→    this.syncService = null;
   206→
   207→    // Save credentials for future auto-login
   208→    MatrixStorage.saveLoginCredentials({
   209→      accessToken: params.accessToken,
   210→      refreshToken: params.refreshToken,
   211→      userId: params.userId,
   212→      deviceId: params.deviceId,
   213→      baseUrl: params.homeserverUrl,
   214→    });
   215→
   216→    // Create a fresh client instance and configure it with the session + sliding sync
   217→    await this.initialize(params.homeserverUrl);
   218→
   219→    if (!this.instance) throw new Error("Failed to initialize client");
   220→
   221→    // Use local variable to help TypeScript with type narrowing
   222→    const client: ClientInterface = this.instance;
   223→
   224→    await client.restoreSession({
   225→      accessToken: params.accessToken,
   226→      refreshToken: params.refreshToken,
   227→      userId: params.userId,
   228→      deviceId: params.deviceId,
   229→      homeserverUrl: params.homeserverUrl,
   230→      oidcData: undefined,
   231→      slidingSyncVersion: SlidingSyncVersion.Native,
   232→    });
   233→
   234→    // Verify the session is valid by making a server request
   235→    // Use the params.userId since client.userId() might not be populated yet
   236→    try {
   237→      this.profile = await client.getProfile(params.userId);
   238→    } catch (error) {
   239→      console.warn("Session validation failed:", error);
   240→      throw new Error("Session is invalid or expired");
   241→    }
   242→
   243→    this.syncService = await client.syncService().finish();
   244→
   245→    if (!this.syncService) throw new Error("Failed to initialize sync service");
   246→
   247→    await this.syncService.start();
   248→    await client.encryption().waitForE2eeInitializationTasks();
   249→
   250→    // Check if we need to bootstrap cross-signing or enable backups
   251→    try {
   252→      const encryption = client.encryption();
   253→      const backupExists = await encryption.backupExistsOnServer();
   254→      console.log("Backup exists on server:", backupExists);
   255→      console.log(
   256→        "Current verification state:",
   257→        encryption.verificationState(),
   258→      );
   259→
   260→      // If no backup exists and we're the only device, we might need to set one up
   261→      const isLastDevice = await encryption.isLastDevice();
   262→      console.log("Is last device:", isLastDevice);
   263→
   264→      if (!backupExists) {
   265→        console.log("Enabling backups for cross-signing...");
   266→        await encryption.enableBackups();
