   348→  /** Manually refresh the room list and update the atom */
   349→  public static refreshRoomList = async () => {
   350→    if (!this.instance) return;
   351→
   352→    try {
   353→      const roomsArray = this.getRooms();
   354→
   355→      const sortedRooms = await Promise.all(
   356→        roomsArray.map(async (room) => ({
   357→          room,
   358→          timestamp: (await room.latestEvent())?.timestamp || 0,
   359→        })),
   360→      );
   361→
   362→      const filteredAndSortedRooms = sortedRooms
   363→        .filter(({ room }) => {
   364→          const membership = room.membership();
   365→
   366→          return (
   367→            membership !== Membership.Banned &&
   368→            membership !== Membership.Left &&
   369→            membership !== Membership.Knocked
   370→          );
   371→        })
   372→        .sort((a, b) => {
   373→          const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
   374→          const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
   375→          if (aInvited !== bInvited) return bInvited - aInvited;
   376→
   377→          return Number(b.timestamp) - Number(a.timestamp);
   378→        });
   379→
   380→      MatrixJotaiStore.set(
   381→        MatrixAtoms.roomList,
   382→        filteredAndSortedRooms.map(({ room }) => room),
   383→      );
   384→    } catch (error) {
   385→      console.error("Failed to refresh room list:", error);
   386→    }
   387→  };
