   431→  public static deactivateAccount = async (password: string) => {
   432→    if (!this.instance) throw new Error("Client not initialized");
   433→
   434→    try {
   435→      // First request with undefined auth_data (will always fail per UIA spec)
   436→      try {
   437→        await this.instance.deactivateAccount(undefined, true);
   438→      } catch {
   439→        // Expected to fail
   440→      }
   441→
   442→      console.log(this.instance.userId(), "userId");
   443→      const userId = this.instance.userId();
