   449→          password,
   450→        }),
   451→      });
   452→
   453→      // Step 4: Second request with auth data
   454→      await this.instance.deactivateAccount(authData, true);
   455→
   456→      // After successful deactivation, clean up local data
   457→      await this.logout();
