   543→  public static forwardMessage = async (
   544→    roomId: string,
   545→    event: EventTimelineItem,
   546→    messageType: ForwardMessageType,
   547→  ) => {
   548→    if (!this.instance) throw new Error("Client not initialized");
   549→    const room = this.instance.getRoom(roomId);
   550→    if (!room) throw new Error("Room not found");
   551→    const timeline = await room.timeline();
   552→    if (!timeline) throw new Error("Timeline not found");
   553→
   554→    if (messageType === "text") {
   555→      const textContent = this.getTextContent(event);
   556→      if (!textContent) throw new Error("Text content not found");
   557→      const messageContent = messageEventContentFromMarkdown(textContent);
   558→      await timeline.send(messageContent);
   559→      return;
   560→    }
   561→
   562→    if (messageType === "image") {
   563→      const imageContent = this.getImageContent(event);
   564→      if (!imageContent) throw new Error("Image content not found");
   565→
   566→      const mediaFile = await this.instance.getMediaFile(
   567→        imageContent.source,
   568→        imageContent.filename,
   569→        imageContent.info?.mimetype || "image/jpeg",
   570→        true,
   571→        undefined,
   572→      );
   573→
   574→      const filePath = mediaFile.path();
   575→      const fileSource: UploadParameters = {
   576→        source: new UploadSource.File({ filename: filePath }),
   577→        caption: imageContent.caption || undefined,
   578→        formattedCaption: undefined,
   579→        mentions: undefined,
   580→        inReplyTo: undefined,
   581→      };
   582→
   583→      const imageHandle = timeline.sendImage(
   584→        fileSource,
   585→        new UploadSource.File({ filename: filePath }),
   586→        {
   587→          height: imageContent.info?.height || BigInt(0),
   588→          width: imageContent.info?.width || BigInt(0),
   589→          mimetype: imageContent.info?.mimetype || "image/jpeg",
   590→          size: imageContent.info?.size || BigInt(0),
   591→          thumbnailInfo: imageContent.info?.thumbnailInfo,
   592→          thumbnailSource: undefined,
   593→          blurhash: imageContent.info?.blurhash || "",
   594→          isAnimated: false,
   595→        },
   596→      );
   597→      await imageHandle.join();
   598→      return;
   599→    }
   600→
   601→    if (messageType === "video") {
   602→      const videoContent = this.getVideoContent(event);
   603→      if (!videoContent) throw new Error("Video content not found");
   604→
   605→      const mediaFile = await this.instance.getMediaFile(
   606→        videoContent.source,
   607→        videoContent.filename,
   608→        videoContent.info?.mimetype || "video/mp4",
   609→        true,
   610→        undefined,
   611→      );
   612→
   613→      const filePath = mediaFile.path();
   614→      const fileSource: UploadParameters = {
   615→        source: new UploadSource.File({ filename: filePath }),
   616→        caption: videoContent.caption || undefined,
   617→        formattedCaption: undefined,
   618→        mentions: undefined,
   619→        inReplyTo: undefined,
   620→      };
   621→
   622→      const videoHandle = timeline.sendVideo(
   623→        fileSource,
   624→        new UploadSource.File({ filename: filePath }),
   625→        {
   626→          height: videoContent.info?.height || BigInt(0),
   627→          width: videoContent.info?.width || BigInt(0),
   628→          mimetype: videoContent.info?.mimetype || "video/mp4",
   629→          size: videoContent.info?.size || BigInt(0),
   630→          duration: videoContent.info?.duration || 0,
   631→          thumbnailInfo: videoContent.info?.thumbnailInfo,
   632→          thumbnailSource: undefined,
   633→          blurhash: videoContent.info?.blurhash || "",
   634→        },
   635→      );
   636→      await videoHandle.join();
   637→      return;
   638→    }
   639→
   640→    if (messageType === "audio") {
   641→      const audioContent = this.getAudioContent(event);
   642→      if (!audioContent) throw new Error("Audio content not found");
   643→
   644→      const mediaFile = await this.instance.getMediaFile(
   645→        audioContent.source,
   646→        audioContent.filename,
   647→        audioContent.info?.mimetype || "audio/mpeg",
   648→        true,
   649→        undefined,
   650→      );
   651→
   652→      const filePath = mediaFile.path();
   653→      const fileSource: UploadParameters = {
   654→        source: new UploadSource.File({ filename: filePath }),
   655→        caption: undefined,
   656→        formattedCaption: undefined,
   657→        mentions: undefined,
   658→        inReplyTo: undefined,
   659→      };
   660→
   661→      const audioHandle = timeline.sendAudio(fileSource, {
   662→        mimetype: audioContent.info?.mimetype || "audio/mpeg",
   663→        size: audioContent.info?.size || BigInt(0),
   664→        duration: audioContent.info?.duration || 0,
   665→      });
   666→      await audioHandle.join();
   667→      return;
   668→    }
   669→
   670→    if (messageType === "file") {
   671→      const fileContent = this.getFileContent(event);
   672→      if (!fileContent) throw new Error("File content not found");
   673→
   674→      const mediaFile = await this.instance.getMediaFile(
   675→        fileContent.source,
   676→        fileContent.filename,
   677→        fileContent.info?.mimetype || "application/octet-stream",
   678→        true,
   679→        undefined,
   680→      );
   681→
   682→      const filePath = mediaFile.path();
   683→      timeline.sendFile(
