   685→          source: new UploadSource.File({ filename: filePath }),
   686→          caption: undefined,
   687→          formattedCaption: undefined,
   688→          mentions: undefined,
   689→          inReplyTo: undefined,
   690→        },
   691→        {
   692→          size: fileContent.info?.size || BigInt(0),
   693→          mimetype: fileContent.info?.mimetype || "application/octet-stream",
   694→          thumbnailInfo: undefined,
   695→          thumbnailSource: undefined,
   696→        },
   697→      );
   698→      return;
   699→    }
   700→
   701→    throw new Error(`Unsupported message type: ${messageType}`);
   702→  };
