   777→    userId: string,
   778→  ): Promise<string> => {
   779→    if (!this.instance) throw new Error("Client not initialized");
   780→
   781→    try {
   782→      // Check if a direct room already exists with this user
   783→      const rooms = this.instance.rooms();
   784→      for (const room of rooms) {
   785→        const roomInfo = await room.roomInfo();
   786→        if (roomInfo?.isDirect) {
   787→          const members = await room.members();
   788→          const memberList = members.nextChunk(100000) ?? [];
   789→          const hasUser = memberList.some((member) => member.userId === userId);
   790→          if (hasUser) {
   791→            return room.id();
   792→          }
   793→        }
   794→      }
   795→
   796→      // If no direct room exists, create one
   797→      const roomOptions: CreateRoomParameters = {
   798→        name: undefined,
   799→        topic: undefined,
   800→        preset: RoomPreset.PrivateChat,
   801→        avatar: undefined,
   802→        isEncrypted: true,
   803→        isDirect: true,
   804→        visibility: new RoomVisibility.Private(),
   805→        invite: [userId],
   806→        powerLevelContentOverride: undefined,
   807→        joinRuleOverride: undefined,
   808→        historyVisibilityOverride: undefined,
   809→        canonicalAlias: undefined,
   810→      };
   811→
   812→      const roomId = await this.instance.createRoom(roomOptions);
   813→      return roomId;
   814→    } catch (error) {
   815→      throw new Error(`Failed to get or create direct room: ${error}`);
