  1483→   * Use this to restore access to encrypted message */
  1484→  public static recoverWithKey = async (recoveryKey: string) => {
  1485→    if (!this.instance) throw new Error("Client not initialized");
  1486→
  1487→    const encryption = this.instance.encryption();
  1488→    await encryption.recover(recoveryKey);
  1489→
  1490→    console.log("✅ Successfully recovered using recovery key!");
  1491→  };
  1492→
  1493→  /** Disable recovery (removes backup and recovery key)
  1494→   * Warning: This will prevent you from recovering encrypted messages */
  1495→  public static disableRecovery = async () => {
  1496→    if (!this.instance) throw new Error("Client not initialized");
  1497→
  1498→    const encryption = this.instance.encryption();
  1499→    await encryption.disableRecovery();
  1500→
  1501→    console.log("⚠️ Recovery disabled");
  1502→  };
  1503→
  1504→  public static resetIdentity = async () => {
  1505→    if (!this.instance) throw new Error("Client not initialized");
  1506→    await this.instance.encryption().resetIdentity();
  1507→    console.log("✅ Identity reset successfully");
  1508→  };
  1509→
  1510→  // PUSH NOTIFICATIONS METHODS
  1511→
  1512→  /** Get all pushers registered for this user */
  1513→  public static getPushers = async () => {
  1514→    if (!this.instance) throw new Error("Client not initialized");
  1515→
  1516→    const session = this.instance.session();
  1517→    if (!session) throw new Error("No active session");
  1518→
  1519→    try {
  1520→      const response = await fetch(
  1521→        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSHERS_GET}`,
  1522→        {
  1523→          method: "GET",
  1524→          headers: {
  1525→            "Content-Type": "application/json",
  1526→            Authorization: `Bearer ${session.accessToken}`,
  1527→          },
  1528→        },
  1529→      );
  1530→
  1531→      if (!response.ok) {
  1532→        const errorText = await response.text();
  1533→        throw new Error(
  1534→          `Failed to get pushers: ${response.status} - ${errorText}`,
  1535→        );
  1536→      }
  1537→
  1538→      const data = await response.json();
  1539→      return data.pushers || [];
  1540→    } catch (error) {
  1541→      console.error("Failed to get pushers:", error);
  1542→      throw error;
  1543→    }
  1544→  };
  1545→
  1546→  /** Check if a pusher is already registered for this device */
  1547→  public static isPusherRegistered = async (pushToken: string) => {
  1548→    try {
  1549→      const pushers = await this.getPushers();
  1550→      if (!this.instance) throw new Error("Client not initialized");
  1551→      const session = this.instance.session();
  1552→      if (!session) throw new Error("No active session");
  1553→
  1554→      return pushers.some(
  1555→        (pusher: {
  1556→          pushkey: string;
  1557→          app_id: string;
  1558→          device_display_name: string;
  1559→        }) =>
  1560→          pusher.pushkey === pushToken &&
  1561→          pusher.app_id === APP_ID &&
  1562→          pusher.device_display_name === session.deviceId,
  1563→      );
  1564→    } catch (error) {
  1565→      console.error("Failed to check pusher registration:", error);
  1566→      return false;
  1567→    }
  1568→  };
  1569→
  1570→  /** Register a pusher with the homeserver for push notifications */
  1571→  public static setPusher = async (pushToken: string) => {
  1572→    if (!this.instance) throw new Error("Client not initialized");
  1573→
  1574→    const session = this.instance.session();
  1575→    if (!session) throw new Error("No active session");
  1576→
  1577→    const pusherData = {
  1578→      pushkey: pushToken,
  1579→      kind: "http",
  1580→      app_id: APP_ID,
  1581→      app_display_name: "Cloak",
  1582→      device_display_name: session.deviceId || "Mobile Device",
  1583→      profile_tag: "", // Optional: for multiple pushers per device
  1584→      lang: "en",
  1585→      data: {
  1586→        url: `${SygnalURL}/${MATRIX_ENDPOINTS.PUSH_GATEWAY_URL}`,
  1587→      },
  1588→    };
  1589→
  1590→    try {
  1591→      const response = await fetch(
  1592→        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSHERS_SET}`,
  1593→        {
  1594→          method: "POST",
  1595→          headers: {
  1596→            "Content-Type": "application/json",
  1597→            Authorization: `Bearer ${session.accessToken}`,
  1598→          },
  1599→          body: JSON.stringify(pusherData),
  1600→        },
  1601→      );
  1602→
  1603→      if (!response.ok) {
  1604→        console.log("Failed to set pusher:", response);
  1605→        const errorText = await response.text();
  1606→        throw new Error(
  1607→          `Failed to set pusher: ${response.status} - ${errorText}`,
  1608→        );
  1609→      }
  1610→
  1611→      return true;
  1612→    } catch (error) {
  1613→      console.error("Failed to register pusher:", error);
  1614→      throw error;
  1615→    }
  1616→  };
  1617→
  1618→  /** Remove a pusher from the homeserver */
  1619→  public static removePusher = async (pushToken: string) => {
  1620→    if (!this.instance) throw new Error("Client not initialized");
