  1625→    const pusherData = {
  1626→      pushkey: pushToken,
  1627→      kind: null, // Setting kind to null removes the pusher
  1628→      app_id: APP_ID,
  1629→    };
  1630→
  1631→    try {
  1632→      const response = await fetch(
  1633→        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSHERS_SET}`,
  1634→        {
  1635→          method: "POST",
  1636→          headers: {
  1637→            "Content-Type": "application/json",
  1638→            Authorization: `Bearer ${session.accessToken}`,
  1639→          },
  1640→          body: JSON.stringify(pusherData),
  1641→        },
  1642→      );
  1643→
  1644→      if (!response.ok) {
  1645→        const errorText = await response.text();
  1646→        throw new Error(
  1647→          `Failed to remove pusher: ${response.status} - ${errorText}`,
  1648→        );
  1649→      }
  1650→
  1651→      console.log("Pusher removed successfully from homeserver");
